from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

PAYLOAD = ""

raw = gzip.decompress(base64.b64decode(PAYLOAD))
expected = "d58381e1dd7c6effe194cfc8242eefa0d8ac40548cffd1fb42c2d320294a8694"
actual = hashlib.sha256(raw).hexdigest()
if actual != expected:
    raise RuntimeError(f"batch36 payload checksum mismatch: {actual}")

virtual_path = Path(__file__).with_name("batch36_house_plan_facade_video.py")
namespace = {"__name__": "__main__", "__file__": str(virtual_path)}
exec(compile(raw.decode("utf-8"), str(virtual_path), "exec"), namespace)
